data class AssignPaymentCardToDisputeCommand(@Id  val disputeId: UUID, val assignment: PaymentCard )
data class UnAssignPaymentCardFromDisputeCommand(@Id  val disputeId: UUID )

// multiple association commands


// Consent Commands
data class CreateConsentCommand(
    @Id var consentId: UUID? = null,
    var grantedOn:  Date? = null,
    var expiresOn:  Date? = null,
    @Enumerated(EnumType.STRING) var consentType: ConsentType? = null,
    @Enumerated(EnumType.STRING) var status: ConsentStatus? = null
)

data class UpdateConsentCommand(
    @Id var consentId: UUID? = null,
    var grantedOn:  Date? = null,
    var expiresOn:  Date? = null,
    var customer: Customer? = null,
    var bank: Bank? = null,
    var authorizedAccounts:  Set<Account>? = null,
    var thirdPartyProvider: ThirdPartyProvider? = null,
    @Enumerated(EnumType.STRING) var consentType: ConsentType? = null,
    @Enumerated(EnumType.STRING) var status: ConsentStatus? = null
)

data class DeleteConsentCommand(@Id  var consentId: UUID? = null)

// single association commands
data class AssignCustomerToConsentCommand(@Id  val consentId: UUID, val assignment: Customer )
data class UnAssignCustomerFromConsentCommand(@Id  val consentId: UUID )
data class AssignBankToConsentCommand(@Id  val consentId: UUID, val assignment: Bank )
data class UnAssignBankFromConsentCommand(@Id  val consentId: UUID )
data class AssignThirdPartyProviderToConsentCommand(@Id  val consentId: UUID, val assignment: ThirdPartyProvider )
data class UnAssignThirdPartyProviderFromConsentCommand(@Id  val consentId: UUID )

// multiple association commands
data class AssignAuthorizedAccountsToConsentCommand(@Id  val consentId: UUID, val addTo: Account )
data class RemoveAuthorizedAccountsFromConsentCommand(@Id  val consentId: UUID, val removeFrom: Account )


// ThirdPartyProvider Commands
data class CreateThirdPartyProviderCommand(
    @Id var thirdPartyProviderId: UUID? = null,
    var name: String? = null,
    var registrationId: String? = null,
    var website: String? = null
)

data class UpdateThirdPartyProviderCommand(
    @Id var thirdPartyProviderId: UUID? = null,
    var name: String? = null,
    var registrationId: String? = null,
    var website: String? = null,
    var bank: Bank? = null,
    var consents:  Set<Consent>? = null
)

data class DeleteThirdPartyProviderCommand(@Id  var thirdPartyProviderId: UUID? = null)

// single association commands
data class AssignBankToThirdPartyProviderCommand(@Id  val thirdPartyProviderId: UUID, val assignment: Bank )
data class UnAssignBankFromThirdPartyProviderCommand(@Id  val thirdPartyProviderId: UUID )

// multiple association commands
data class AssignConsentsToThirdPartyProviderCommand(@Id  val thirdPartyProviderId: UUID, val addTo: Consent )
data class RemoveConsentsFromThirdPartyProviderCommand(@Id  val thirdPartyProviderId: UUID, val removeFrom: Consent )



